// Original training models, aligned to the 19 task lines of the 2026 exam.
// Each model has 30 deterministic, stable numerical variants, not random answers.
export const examLines=[
 [1,'Планиметрия','Треугольники, окружности, площади'],[2,'Векторы','Координаты, длина, скалярное произведение'],
 [3,'Стереометрия','Объёмы, поверхности, сечения'],[4,'Простая вероятность','Равновозможные исходы'],
 [5,'Сложная вероятность','Независимость, условная вероятность, схемы испытаний'],[6,'Простые уравнения','Показательные, логарифмические, рациональные, корни'],
 [7,'Вычисления и преобразования','Степени, логарифмы, тригонометрия, радикалы'],[8,'Производная и графики','Касательная, знаки производной, экстремумы'],
 [9,'Прикладные задачи','Вычисления и уравнения по формулам'],[10,'Текстовые задачи','Движение, работа, смеси'],
 [11,'Графики функций','Прямая, парабола, гипербола, экспонента'],[12,'Исследование функций','Экстремумы и значения на отрезке'],
 [13,'Уравнения с отбором корней','Тригонометрия, показатели, логарифмы'],[14,'Стереометрия с доказательством','Углы, расстояния, сечения'],
 [15,'Неравенства','Интервалы, модули, рационализация'],[16,'Экономические задачи','Кредиты, вклады, оптимизация'],
 [17,'Планиметрия с доказательством','Подобие, центры окружностей, трапеции'],[18,'Задачи с параметрами','Число корней, замены и анализ функции'],
 [19,'Числа и логика','Делимость, оценки, конструкции, доказательства']
].map(([number,name,description])=>({number,name,description,part:number<=12?1:2}));
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const decimal=n=>String(Number(n.toFixed(9)));
const expr=s=>`<div class="math-expression">${escape(s)}</div>`;
const generated=[];
const family=(n,key,level,title,tag,fn)=>{
 for(let i=1;i<=30;i++){
  const q=fn(i),plain=q.formula||'';
  generated.push({id:`e26-${n}-${key}-${i}`,ege:n,type:`n${n}`,level,title,tag,template:key,variant:i,
   prompt:q.prompt,plain,formula:plain?expr(plain):'',answer:String(q.answer),answerKind:q.answerKind||(n===13||n===15||n===18?'set':'number'),
   answerLabel:q.answerLabel||(n===13?'Корни из пункта б)':n===19?'Ответ к пункту в)':n===14||n===17?'Ответ к пункту б)':'Твой ответ'),
   hints:q.hints,steps:q.steps,graph:q.graph,diagram:q.diagram,audit:q.audit||{},
   criteria:q.criteria||(n>=13?['Переходы обоснованы и ограничения учтены.','Перечислены все случаи; границы проверены.','Ответ получен из записанного решения.']:[]),source:'Авторский числовой вариант · модель ЕГЭ-2026'});
 }
};
const points=(xmin,xmax,fn,label='')=>({xmin,xmax,curves:[{fn,label}]});
// 1. Plane geometry, short answers.
family(1,'right',1,'Прямоугольный треугольник','Теорема Пифагора',i=>{const k=i+1;return {
 prompt:`В треугольнике ABC угол C прямой, AC = ${3*k}, BC = ${4*k}. Найдите AB.`,formula:'∠C = 90°',answer:5*k,diagram:'right-triangle',audit:{k},
 hints:['Отметь прямой угол и гипотенузу.','Примени теорему Пифагора к двум катетам.','Извлеки положительный квадратный корень из суммы квадратов.'],
 steps:[`AB² = AC² + BC² = ${9*k*k} + ${16*k*k} = ${25*k*k}.`,`Длина положительна: AB = ${5*k}.`]};});
family(1,'circle',2,'Вписанный угол','Дуги и углы',i=>{const a=10+2*i;return {
 prompt:`Точки A, B и C лежат на окружности. Малая дуга AB равна ${2*a}°. Точка C лежит на большой дуге AB. Найдите угол ACB в градусах.`,answer:a,diagram:'circle',audit:{a},
 hints:['Определи, на какую дугу опирается угол ACB.','Вписанный угол опирается на дугу, не содержащую его вершину.','Вписанный угол равен половине соответствующей дуги.'],steps:[`Угол ACB опирается на малую дугу AB, равную ${2*a}°.`,`∠ACB = ${2*a}/2 = ${a}°.`]};});
family(1,'trapezoid',2,'Площадь трапеции','Средняя линия',i=>{const a=i+3,b=2*i+7,h=2*(i%5+2);return {
 prompt:`Основания трапеции равны ${a} и ${b}, высота равна ${h}. Найдите её площадь.`,answer:(a+b)*h/2,diagram:'trapezoid',audit:{a,b,h},
 hints:['Площадь выражается через высоту и среднюю линию.','Средняя линия равна полусумме оснований.','Умножь среднюю линию на высоту; не потеряй деление на 2.'],steps:[`Средняя линия m = (${a} + ${b})/2 = ${(a+b)/2}.`,`S = mh = ${(a+b)*h/2}.`]};});
family(1,'tangent',3,'Касательная к окружности','Степень точки',i=>{const k=i+1;return {
 prompt:`Из точки P вне окружности проведены касательная PA и секущая PBC; B лежит между P и C. Известно, что PB = ${4*k}, BC = ${5*k}. Найдите PA.`,answer:6*k,audit:{k},
 hints:['В формуле для секущей используются внешний отрезок и вся секущая.','Сначала найди PC как сумму PB и BC.','Используй PA² = PB · PC и выбери положительную длину.'],steps:[`PC = PB + BC = ${9*k}.`,`По теореме о касательной и секущей PA² = ${4*k} · ${9*k} = ${36*k*k}.`,`PA = ${6*k}.`]};});
// 2. Vectors.
family(2,'dot',1,'Скалярное произведение','Координаты векторов',i=>{const a=i+1,b=i%7-3,c=i+4,d=5-i%5;return {
 prompt:`Даны векторы a = (${a}; ${b}) и b = (${c}; ${d}). Найдите a · b.`,formula:'a · b = ?',answer:a*c+b*d,audit:{a,b,c,d},
 hints:['Скалярное произведение не является вектором.','Перемножь одноимённые координаты.','Сложи полученные произведения, учитывая знаки.'],steps:[`a · b = ${a} · ${c} + (${b}) · ${d}.`,`Получаем ${a*c+b*d}.`]};});
family(2,'length',2,'Длина суммы','Операции над векторами',i=>{const k=i+1,a=i-5,b=2*i;return {
 prompt:`Даны a = (${a}; ${b}) и b = (${3*k-a}; ${4*k-b}). Найдите длину a + b.`,answer:5*k,audit:{k,a,b},
 hints:['Сначала сложи векторы по координатам.','Длина вектора (u; v) равна √(u² + v²).','Проверь, не получилась ли известная пифагорова тройка.'],steps:[`a + b = (${3*k}; ${4*k}).`,`|a + b| = √(${9*k*k} + ${16*k*k}) = ${5*k}.`]};});
family(2,'orthogonal',2,'Условие перпендикулярности','Нулевое произведение',i=>{const a=i+2,b=i%5+1;return {
 prompt:`Векторы a = (${a}; ${b}) и b = (t; ${-a*b}) перпендикулярны. Найдите t.`,formula:'a ⟂ b',answer:b*b,audit:{a,b},
 hints:['У перпендикулярных ненулевых векторов скалярное произведение равно нулю.','Запиши линейное уравнение относительно t.','Коэффициент при t отличен от нуля, поэтому деление допустимо.'],steps:[`${a}t + ${b} · (${-a*b}) = 0.`,`${a}t = ${a*b*b}, откуда t = ${b*b}.`]};});
family(2,'space',3,'Векторы в пространстве','Три координаты',i=>{const k=i+1;return {
 audit:{k},prompt:`Даны a = (${k}; ${2*k}; ${3*k}) и b = (${k}; 0; ${-k}). Найдите квадрат длины вектора 2a − b.`,answer:66*k*k,
 hints:['Умножь каждую координату a на 2, затем вычти b.','Квадрат длины — сумма квадратов трёх координат.','Требуется квадрат длины, поэтому корень извлекать не нужно.'],steps:[`2a − b = (${k}; ${4*k}; ${7*k}).`,`|2a − b|² = ${k*k} + ${16*k*k} + ${49*k*k} = ${66*k*k}.`]};});
// 3. Solid geometry.
family(3,'pyramid',1,'Объём пирамиды','Площадь основания',i=>{const a=i+2,b=i+4,h=3*(i%6+1);return {
 prompt:`Основание пирамиды — прямоугольник со сторонами ${a} и ${b}, высота пирамиды равна ${h}. Найдите объём.`,answer:a*b*h/3,diagram:'pyramid',audit:{a,b,h},
 hints:['Высота пирамиды перпендикулярна плоскости основания.','Найди площадь прямоугольного основания.','Объём пирамиды равен одной трети произведения площади основания на высоту.'],steps:[`Sосн = ${a} · ${b} = ${a*b}.`,`V = Sосн · h/3 = ${a*b*h/3}.`]};});
family(3,'cylinder',2,'Поверхность цилиндра','Тела вращения',i=>{const r=i+1,h=i%7+3;return {
 prompt:`Радиус цилиндра равен ${r}, высота равна ${h}. Найдите площадь его полной поверхности, делённую на π.`,answer:2*r*(r+h),diagram:'cylinder',audit:{r,h},
 hints:['Полная поверхность включает боковую часть и два основания.','Запиши 2πrh + 2πr².','Вынеси π и учти, что в ответе требуется S/π.'],steps:[`S = 2π · ${r} · ${h} + 2π · ${r*r}.`,`S/π = 2 · ${r} · (${h} + ${r}) = ${2*r*(r+h)}.`]};});
family(3,'sphere',2,'Сечение шара','Радиус сечения',i=>{const k=i+1;return {
 prompt:`Шар радиуса ${5*k} пересечён плоскостью, удалённой от его центра на ${3*k}. Найдите площадь сечения, делённую на π.`,answer:16*k*k,diagram:'sphere',audit:{k},
 hints:['Сечение шара плоскостью — круг.','Радиус шара, расстояние до плоскости и радиус сечения образуют прямоугольный треугольник.','Найди квадрат радиуса сечения; для S/π достаточно именно его.'],steps:[`r² = (${5*k})² − (${3*k})² = ${16*k*k}.`,`Sсеч = πr², поэтому Sсеч/π = ${16*k*k}.`]};});
family(3,'cone',3,'Конус и цилиндр','Отношение объёмов',i=>{const k=i+1;return {
 prompt:`Конус и цилиндр имеют одинаковые основания и высоты. Объём цилиндра равен ${81*k}. На сколько объём цилиндра больше объёма конуса?`,answer:54*k,diagram:'cylinder',audit:{k},
 hints:['Сравни формулы объёмов при одинаковых r и h.','Объём конуса составляет треть объёма цилиндра.','Из объёма цилиндра вычти объём конуса.'],steps:[`Vкон = ${81*k}/3 = ${27*k}.`,`Разность равна ${81*k} − ${27*k} = ${54*k}.`]};});
// 4. Classical probability; all keys have terminating decimal expansions.
family(4,'balls',1,'Шары в коробке','Классическая вероятность',i=>({prompt:`В коробке 100 шаров: ${i+5} красных, остальные синие. Наугад извлекают один шар. Найдите вероятность того, что он красный.`,answer:decimal((i+5)/100),audit:{i},hints:['Все шары выбираются равновероятно.','Подсчитай число благоприятных исходов.','Раздели благоприятное число на общее.'],steps:[`P = (${i+5})/100 = ${decimal((i+5)/100)}.`]}));
family(4,'tickets',2,'Лотерейные билеты','Дополнительное событие',i=>({prompt:`Из 200 билетов ${2*i+8} выигрышных. Билет выбирают случайно. Найдите вероятность не выиграть.`,answer:decimal(1-(2*i+8)/200),audit:{i},hints:['Удобно рассмотреть противоположное событие.','Вероятность проигрыша равна 1 минус вероятность выигрыша.','Проверь, что ответ лежит между 0 и 1.'],steps:[`Pвыигр = ${2*i+8}/200.`,`Pне выиграть = 1 − Pвыигр = ${decimal(1-(2*i+8)/200)}.`]}));
family(4,'integer',2,'Случайное целое число','Подсчёт исходов',i=>({prompt:`Случайно выбирают целое число от 1 до 100 включительно. Найдите вероятность того, что оно чётное и не превосходит ${2*(i+1)}.`,answer:decimal((i+1)/100),audit:{i},hints:['Нужно одновременное выполнение обоих условий.','Выпиши чётные числа от 2 до указанной верхней границы.','Найди их количество и раздели на 100.'],steps:[`Благоприятны 2, 4, …, ${2*(i+1)}: всего ${i+1} чисел.`,`P = ${i+1}/100 = ${decimal((i+1)/100)}.`]}));
family(4,'sector',3,'Сектор на круге','Геометрическая вероятность',i=>({prompt:`Колесо имеет 100 равных секторов с номерами 1–100. После вращения каждый сектор равновероятен. Найдите вероятность остановки на секторе с номером от ${i+1} до ${3*i+7} включительно.`,answer:decimal((2*i+7)/100),audit:{i},hints:['Оба конца диапазона включены.','Количество целых чисел от m до n включительно равно n − m + 1.','Подели количество подходящих секторов на 100.'],steps:[`Подходящих секторов: (${3*i+7}) − (${i+1}) + 1 = ${2*i+7}.`,`P = ${decimal((2*i+7)/100)}.`]}));
// 5. Multi-step probability.
family(5,'independent',1,'Хотя бы один успех','Независимые события',i=>{const p=(i+10)/100,q=(i+20)/100;return {prompt:`Вероятности попадания двух стрелков равны ${decimal(p)} и ${decimal(q)}. Они стреляют независимо по одному разу. Найдите вероятность хотя бы одного попадания.`,answer:decimal(1-(1-p)*(1-q)),audit:{p,q},hints:['«Хотя бы один» удобно заменить противоположным событием.','Вероятность двух промахов — произведение вероятностей промахов.','Вычти полученную вероятность из 1.'],steps:[`Pдвух промахов = (1 − ${decimal(p)})(1 − ${decimal(q)}).`,`Pхотя бы одного = 1 − Pдвух промахов = ${decimal(1-(1-p)*(1-q))}.`]};});
family(5,'binomial',2,'Два успеха из трёх','Схема Бернулли',i=>{const p=(i+10)/100;return {prompt:`Игрок выполняет три независимые попытки. Успех в каждой имеет вероятность ${decimal(p)}. Найдите вероятность ровно двух успехов.`,answer:decimal(3*p*p*(1-p)),audit:{p},hints:['Не путай «ровно два» с «не менее двух».','Выбери место единственной неудачи: вариантов три.','Для одного порядка вероятность равна p²(1 − p).'],steps:[`Подходят три порядка: УУН, УНУ, НУУ.`,`Вероятность каждого равна (${decimal(p)})²(1 − ${decimal(p)}).`,`Общая вероятность равна ${decimal(3*p*p*(1-p))}.`]};});
family(5,'bayes',3,'Откуда бракованная деталь','Условная вероятность',i=>{const p=(i+1)/100,q=(49-i)/100;return {prompt:`Два станка выпускают поровну деталей. У первого вероятность брака ${decimal(p)}, у второго — ${decimal(q)}. Случайно выбранная деталь оказалась бракованной. Найдите вероятность, что её изготовил первый станок.`,answer:decimal(p/(p+q)),audit:{p,q},hints:['Условие о браке меняет вероятности происхождения детали.','Вычисли вероятность брака как сумму по двум станкам.','Раздели вероятность «первый станок и брак» на общую вероятность брака.'],steps:[`Pбрака = 0,5 · ${decimal(p)} + 0,5 · ${decimal(q)} = 0,25.`,`Pпервый | брак = (0,5 · ${decimal(p)})/0,25 = ${decimal(p/(p+q))}.`]};});
family(5,'reliability',3,'Система с резервом','Дерево событий',i=>{const p=(i+20)/100,q=(i+30)/100;return {prompt:`Устройство работает, если работает блок C и хотя бы один из блоков A, B. Вероятность работы каждого из A, B равна ${decimal(p)}, блока C — ${decimal(q)}. Все блоки независимы. Найдите вероятность работы устройства.`,answer:decimal(q*(1-(1-p)**2)),audit:{p,q},hints:['Сначала рассмотри только параллельные блоки A и B.','Они оба не работают с вероятностью (1 − p)².','Нужна совместная работа C и пары с резервом; события независимы.'],steps:[`Pхотя бы одного из A,B = 1 − (1 − ${decimal(p)})².`,`Pустройства = ${decimal(q)} · [1 − (1 − ${decimal(p)})²] = ${decimal(q*(1-(1-p)**2))}.`]};});
// 6. Simple equations.
family(6,'exponential',1,'Равные основания','Показательное уравнение',i=>{const b=i%4+2,k=i%5+1,h=i-12;return {prompt:'Найдите корень уравнения.',formula:`${b}^(x − (${h})) = ${b**k}`,answer:h+k,audit:{b,k,h},hints:['Представь правую часть степенью основания слева.','При одинаковых положительных основаниях, не равных 1, показатели равны.','Реши линейное уравнение для x.'],steps:[`${b**k} = ${b}^${k}, поэтому x − (${h}) = ${k}.`,`x = ${h+k}.`]};});
family(6,'logarithm',2,'Логарифм по определению','Логарифмическое уравнение',i=>{const b=i%3+2,k=i%4+1,s=i+2;return {prompt:'Найдите корень уравнения.',formula:`log${['','','₂','₃','₄'][b]}(x + ${s}) = ${k}`,answer:b**k-s,audit:{b,k,s},hints:['Запиши ограничение на аргумент логарифма.','По определению логарифма его аргумент равен основанию в указанной степени.','Найди x и проверь положительность аргумента.'],steps:[`ОДЗ: x > ${-s}.`,`x + ${s} = ${b}^${k} = ${b**k}.`,`x = ${b**k-s}, аргумент положителен.`]};});
family(6,'rational',2,'Не потеряй запрет','Рациональное уравнение',i=>{const p=i-10,d=i%6+2;return {prompt:'Найдите корень уравнения.',formula:`(x − (${p+d})) / (x − (${p})) = 2`,answer:p-d,audit:{p,d},hints:['Знаменатель не должен равняться нулю.','На ОДЗ умножь обе части на знаменатель.','После нахождения x проверь запрещённое значение.'],steps:[`ОДЗ: x ≠ ${p}.`,`x − (${p+d}) = 2x − (${2*p}).`,`x = ${p-d}, это не запрещённое значение.`]};});
family(6,'radical',3,'Корень и проверка','Иррациональное уравнение',i=>{const a=i%7+2,s=i+3;return {prompt:'Найдите корень уравнения.',formula:`√(x + ${s}) = ${a}`,answer:a*a-s,audit:{a,s},hints:['Правая часть положительна, возведение в квадрат допустимо.','Запиши x + s = a².','Подставь найденное значение в исходное уравнение.'],steps:[`x + ${s} = ${a*a}.`,`x = ${a*a-s}.`,`Проверка: √(${a*a}) = ${a}.`]};});
// 7. Calculation and simplification.
family(7,'powers',1,'Частное степеней','Свойства степеней',i=>{const b=i+2,n=i%4+1;return {prompt:'Найдите значение выражения.',formula:`${b}^${n+2} / ${b}^${n}`,answer:b*b,audit:{b,n},hints:['При делении степеней с одинаковым основанием показатели вычитаются.','Основание отлично от нуля.','Выполни оставшееся возведение в степень.'],steps:[`${b}^${n+2} / ${b}^${n} = ${b}² = ${b*b}.`]};});
family(7,'logs',2,'Сумма логарифмов','Определение логарифма',i=>{const b=i%3+2,k=i%3+2,m=i+1;return {prompt:'Найдите значение выражения.',formula:`${m} · (log${['','','₂','₃','₄'][b]}${b**k} + log${['','','₂','₃','₄'][b]}${b**3})`,answer:m*(k+3),audit:{b,k,m},hints:['Каждый аргумент — целая степень основания.','По определению логарифм степени основания равен показателю.','Сложи значения, затем учти внешний множитель.'],steps:[`Логарифмы равны ${k} и 3.`,`Выражение равно ${m} · (${k} + 3) = ${m*(k+3)}.`]};});
family(7,'trig',2,'Тригонометрическое тождество','Основное тождество',i=>{const k=i+3,m=2*i+1;return {prompt:'Вычислите выражение. Известно, что sin α ≠ 0 и cos α ≠ 0.',formula:`${k}sin²α + ${k}cos²α + ${m}tg α · ctg α`,answer:k+m,audit:{k,m},hints:['У первых двух слагаемых одинаковый коэффициент.','Используй sin²α + cos²α = 1.','На указанной области tg α · ctg α = 1.'],steps:[`Первые два слагаемых дают ${k}(sin²α + cos²α) = ${k}.`,`Последнее слагаемое равно ${m}.`,`Сумма равна ${k+m}.`]};});
family(7,'roots',3,'Произведение корней','Свойства радикалов',i=>{const k=i+2;return {prompt:'Найдите значение выражения.',formula:`√${3*k*k} · √3`,answer:3*k,audit:{k},hints:['Подкоренные выражения неотрицательны.','Можно объединить корни в один корень из произведения.','Выдели полный квадрат.'],steps:[`√${3*k*k} · √3 = √${9*k*k}.`,`Выражение равно ${3*k}.`]};});
// 8. Actual graphs, generated from analytic functions.
family(8,'minimum',1,'Нуль производной','График f′(x)',i=>{const a=i-15;return {prompt:'На рисунке дан график производной f′(x). Найдите абсциссу точки минимума f(x).',formula:'y = f′(x)',answer:a,graph:points(a-3,a+3,x=>x-a,'f′'),audit:{a},hints:['Смотри на знак производной, а не на высоту графика самой функции.','В точке минимума производная меняет знак с минуса на плюс.','Прочитай абсциссу соответствующего пересечения оси x.'],steps:[`При x < ${a} производная отрицательна, при x > ${a} — положительна.`,`Функция сначала убывает, затем возрастает: минимум при x = ${a}.`]};});
family(8,'increasing',2,'Где функция возрастает','Знак производной',i=>{const a=i-12,b=a+i%8+2;return {prompt:'На рисунке дан график производной f′(x). Найдите длину промежутка возрастания f(x) в показанной области.',formula:'y = f′(x)',answer:b-a,graph:points(a-1,b+1,x=>-(x-a)*(x-b),'f′'),audit:{a,b},hints:['Возрастанию соответствует положительная производная.','Определи две точки, между которыми график выше оси x.','Вычти левую границу промежутка из правой.'],steps:[`Производная положительна при ${a} < x < ${b}.`,`Длина промежутка равна ${b} − (${a}) = ${b-a}.`]};});
family(8,'tangent',2,'Наклон касательной','Геометрический смысл производной',i=>{const a=i%4-2,k=i+1;return {prompt:`Касательная к графику функции в точке с абсциссой x₀ проходит через точки A(${a}; 1) и B(${a+2}; ${1+2*k}). Найдите f′(x₀).`,formula:'f′(x₀) = kкасательной',answer:k,graph:{...points(a-1,a+3,x=>1+k*(x-a),'касательная'),points:[[a,1,'A'],[a+2,1+2*k,'B']]},audit:{a,k},hints:['Производная в точке равна угловому коэффициенту касательной.','Для двух точек наклон равен отношению приращения y к приращению x.','Вычисли (yB − yA)/(xB − xA).'],steps:[`f′(x₀) = (${1+2*k} − 1)/((${a+2}) − (${a})).`,`Производная равна ${k}.`]};});
family(8,'extrema',3,'Две точки минимума','Смена знаков f′',i=>{const a=i-12,b=a+2,c=a+5;return {prompt:'На рисунке дан график производной f′(x). Найдите сумму абсцисс всех точек минимума f(x) в показанной области.',formula:'y = f′(x)',answer:a+c,graph:points(a-1,c+1,x=>(x-a)*(x-b)*(x-c)/8,'f′'),audit:{a,b,c},hints:['Найди все нули производной на графике.','Оставь только переходы производной с минуса на плюс.','Нужна сумма абсцисс, а не количество точек.'],steps:[`Знаки производной слева направо: −, +, −, +.`,`Минимумы расположены при x = ${a} и x = ${c}; при x = ${b} — максимум.`,`Сумма абсцисс минимумов равна ${a+c}.`]};});
// 9. Applied formulas.
family(9,'energy',1,'Кинетическая энергия','Физическая формула',i=>{const m=2*(i+1),v=i%7+3,E=m*v*v/2;return {prompt:`Кинетическая энергия тела E = mv²/2. Масса равна ${m} кг, энергия — ${E} Дж. Найдите скорость v в м/с.`,formula:'E = mv²/2, v ≥ 0',answer:v,audit:{m,v,E},hints:['Подставь массу и энергию в формулу.','Вырази квадрат скорости: v² = 2E/m.','Скорость по условию неотрицательна.'],steps:[`v² = 2 · ${E}/${m} = ${v*v}.`,`v = ${v} м/с.`]};});
family(9,'electric',2,'Мощность тока','Выражение переменной',i=>{const R=5*(i+1),I=i%4+2,U=R*I,P=R*I*I;return {prompt:`Мощность нагревателя P = U²/R, где R = ${R} Ом. Найдите положительное напряжение U в вольтах, при котором P = ${P} Вт.`,formula:'P = U²/R',answer:U,audit:{R,P,U},hints:['Подставь числовые данные.','Умножь на R, чтобы получить U².','Выбери положительный корень: это прямо указано в условии.'],steps:[`U² = PR = ${P} · ${R} = ${U*U}.`,`U = ${U} В.`]};});
family(9,'cooling',3,'Охлаждение по формуле','Показательная модель',i=>{const a=15+i,d=10*(i+1),k=i%4+1;return {prompt:`Температура тела меняется по закону T(t) = ${a} + ${d} · 2^(−t/${k}), где t — минуты. Через сколько минут температура станет равна ${a+d/4}°?`,formula:`T(t) = ${a} + ${d} · 2^(−t/${k})`,answer:2*k,audit:{a,d,k},hints:['Вычти температуру окружающей среды из обеих частей.','Подели на начальную разность температур.','Представь полученную долю степенью двойки и приравняй показатели.'],steps:[`2^(−t/${k}) = (${a+d/4} − ${a})/${d} = 1/4 = 2⁻².`,`−t/${k} = −2, поэтому t = ${2*k} мин.`]};});
family(9,'freefall',3,'Скорость падения','Иррациональная модель',i=>{const k=i+1,h=5*k*k;return {prompt:`Скорость тела после падения с высоты h без начальной скорости задаётся формулой v = √(2gh). Примите g = 10 м/с², h = ${h} м. Найдите v в м/с.`,formula:'v = √(2gh)',answer:10*k,audit:{h,k},hints:['Проверь единицы измерения: они уже согласованы.','Подставь g и h под корень.','Найди положительный квадратный корень.'],steps:[`v = √(2 · 10 · ${h}) = √${100*k*k}.`,`v = ${10*k} м/с.`]};});
// 10. Word problems.
family(10,'work',1,'Две бригады','Совместная работа',i=>{const k=i+2;return {prompt:`Первая бригада выполняет работу за ${2*k} часов, вторая — за ${3*k} часов. За сколько часов они выполнят её вместе, если производительности постоянны?`,answer:decimal(6*k/5),audit:{k},hints:['Прими весь объём работы за 1.','При совместной работе складывают производительности, не времена.','Время равно объёму работы, делённому на общую производительность.'],steps:[`Общая производительность: 1/${2*k} + 1/${3*k} = 5/${6*k}.`,`Время равно ${6*k}/5 = ${decimal(6*k/5)} ч.`]};});
family(10,'motion',2,'Два автомобиля','Уравнение движения',i=>{const v=i+5,D=2*v*(v+3);return {prompt:`Два автомобиля проехали по ${D} км. Скорость второго на 3 км/ч больше скорости первого, поэтому он затратил на 6 часов меньше. Найдите скорость первого в км/ч.`,answer:v,audit:{v,D},hints:['Обозначь меньшую скорость через v > 0.','Разность времён равна D/v − D/(v + 3).','Приведи уравнение к квадратному и выбери положительный корень.'],steps:[`${D}/v − ${D}/(v + 3) = 6.`,`v(v + 3) = ${D}/2 = ${v*(v+3)}.`,`(v − ${v})(v + ${v+3}) = 0. Положительный корень: v = ${v}.`]};});
family(10,'alloy',2,'Смешивание растворов','Баланс вещества',i=>{const m=10*(i+1),p=i+10,q=i+40;return {prompt:`Смешали ${m} кг раствора с концентрацией ${p}% и ${2*m} кг раствора с концентрацией ${q}%. Найдите процентную концентрацию смеси.`,answer:i+30,audit:{m,p,q},hints:['Найди массу растворённого вещества в каждом растворе.','Сложи массы вещества и массы растворов отдельно.','Доля вещества в смеси равна суммарной массе вещества, делённой на общую массу.'],steps:[`Концентрация в процентах: (${m} · ${p} + ${2*m} · ${q})/${3*m}.`,`После сокращения получаем (${p} + 2 · ${q})/3 = ${i+30}%.`]};});
family(10,'average',3,'Туда и обратно','Средняя скорость',i=>{const k=i+10,v=3*k,w=6*k;return {prompt:`Путешественник проехал путь из A в B со скоростью ${v} км/ч, а обратно тем же путём — со скоростью ${w} км/ч. Найдите среднюю скорость за всю поездку.`,answer:4*k,audit:{v,w,k},hints:['Средняя скорость — весь путь, делённый на всё время.','Обозначь длину одного плеча через S.','Вычисли 2S/(S/v + S/w); величина S сократится.'],steps:[`vср = 2/(1/${v} + 1/${w}).`,`vср = 2 · ${v} · ${w}/(${v} + ${w}) = ${4*k} км/ч.`]};});
// 11. Functions defined by a graph and marked points.
family(11,'line',1,'Прямая через две точки','Линейная функция',i=>{const h=i%5-2,c=i+1,k=i%4+1;return {prompt:`Прямая f(x) проходит через A(${h}; ${c}) и B(${h+1}; ${c+k}), отмеченные на графике. Найдите f(${h+3}).`,formula:'f(x) = kx + b',answer:c+3*k,graph:{...points(h-1,h+4,x=>c+k*(x-h),'f'),points:[[h,c,'A'],[h+1,c+k,'B']]},audit:{h,c,k},hints:['Найди наклон по двум отмеченным точкам.','Запиши f(x) = yA + k(x − xA).','Подставь нужное значение x.'],steps:[`Наклон k = (${c+k} − ${c})/((${h+1}) − (${h})) = ${k}.`,`f(${h+3}) = ${c} + ${k} · 3 = ${c+3*k}.`]};});
family(11,'parabola',2,'Восстанови параболу','Вершина и точка',i=>{const h=i%5-2,c=i-10,a=i%4+1;return {prompt:`Вершина параболы f(x) = a(x − h)² + c — V(${h}; ${c}). Она проходит через P(${h+1}; ${c+a}). Найдите f(${h+2}).`,formula:'f(x) = a(x − h)² + c',answer:4*a+c,graph:{...points(h-2,h+2,x=>a*(x-h)**2+c,'f'),points:[[h,c,'V'],[h+1,c+a,'P']]},audit:{h,c,a},hints:['Координаты вершины сразу определяют h и c.','Подставь координаты точки P, чтобы найти a.','В искомой точке расстояние по оси x от вершины равно 2.'],steps:[`f(${h+1}) = a · 1² + (${c}) = ${c+a}, значит a = ${a}.`,`f(${h+2}) = ${a} · 2² + (${c}) = ${4*a+c}.`]};});
family(11,'hyperbola',3,'Сдвинутая гипербола','Обратная пропорциональность',i=>{const h=i%5-2,c=i-12,k=2*(i+2);return {prompt:`Гипербола имеет вид f(x) = k/(x − h) + c. Её асимптоты x = ${h}, y = ${c}; отмечена точка P(${h+1}; ${k+c}). Найдите f(${h+2}).`,formula:'f(x) = k/(x − h) + c',answer:k/2+c,graph:{...points(h-4,h+4,x=>Math.abs(x-h)<.08?NaN:k/(x-h)+c,'f'),points:[[h+1,k+c,'P']],asymptote:h},audit:{h,c,k},hints:['Сдвиги h и c задаются асимптотами.','Подставь координаты P для определения k.','В искомой точке знаменатель равен 2.'],steps:[`Из точки P: ${k+c} = k/1 + (${c}), поэтому k = ${k}.`,`f(${h+2}) = ${k}/2 + (${c}) = ${k/2+c}.`]};});
family(11,'exponent',3,'Показательная функция','Восстановление основания',i=>{const h=i%4-2,c=i-15,b=i%4+2;return {prompt:`График f(x) = b^(x − h) + c имеет горизонтальную асимптоту y = ${c} и проходит через A(${h}; ${c+1}), B(${h+1}; ${c+b}). Найдите f(${h+2}).`,formula:'f(x) = b^(x − h) + c',answer:b*b+c,graph:{...points(h-2,h+2,x=>b**(x-h)+c,'f'),points:[[h,c+1,'A'],[h+1,c+b,'B']]},audit:{h,c,b},hints:['Точка A соответствует нулевому показателю степени.','При переходе от A к B показатель увеличивается на 1.','Найди b и вычисли функцию при показателе 2.'],steps:[`При x = ${h+1} получаем b + (${c}) = ${c+b}, поэтому b = ${b}.`,`f(${h+2}) = ${b}² + (${c}) = ${b*b+c}.`]};});
// 12. Derivative and function analysis.
family(12,'cubic',1,'Точка максимума кубической функции','Знак производной',i=>{const a=i+1,c=i-8;return {prompt:'Найдите абсциссу точки локального максимума функции.',formula:`y = x³ − ${3*a*a}x + (${c})`,answer:-a,audit:{a,c},hints:['Найди производную многочлена.','Разложи производную на множители.','Для максимума нужна смена знака производной с плюса на минус.'],steps:[`y′ = 3x² − ${3*a*a} = 3(x − ${a})(x + ${a}).`,`Знаки: + при x < ${-a}, − при ${-a} < x < ${a}, + при x > ${a}.`,`В точке x = ${-a} расположен локальный максимум.`]};});
family(12,'segment',2,'Наибольшее значение на отрезке','Экстремум и концы',i=>{const a=i-12,b=i+5,d=i%5+1;return {prompt:`Найдите наибольшее значение функции на отрезке [${a-2}; ${a+d}].`,formula:`y = x² − (${2*a})x + (${b})`,answer:b-a*a+Math.max(4,d*d),audit:{a,b,d},hints:['Выделение полного квадрата поможет увидеть вершину.','Парабола направлена вверх, поэтому максимум на отрезке достигается на одном из концов.','Вычисли оба граничных значения и выбери большее.'],steps:[`y = (x − (${a}))² + (${b-a*a}).`,`На концах квадраты равны 4 и ${d*d}.`,`Максимум равен ${b-a*a} + ${Math.max(4,d*d)} = ${b-a*a+Math.max(4,d*d)}.`]};});
family(12,'log',3,'Минимум логарифмической функции','Производная ln',i=>{const a=i-15,b=i%6+2;return {prompt:'Найдите абсциссу точки минимума функции на её области определения.',formula:`y = x − (${a}) − ${b} ln(x − (${a}))`,answer:a+b,audit:{a,b},hints:['Сначала запиши область определения логарифма.','Найди производную: 1 − b/(x − a).','Исследуй знак на ОДЗ; одного нуля производной недостаточно.'],steps:[`ОДЗ: x > ${a}. y′ = 1 − ${b}/(x − (${a})) = (x − (${a+b}))/(x − (${a})).`,`Знаменатель на ОДЗ положителен. До x = ${a+b} производная отрицательна, после — положительна.`,`Точка минимума: x = ${a+b}.`]};});
family(12,'exp',3,'Произведение с экспонентой','Правило произведения',i=>{const a=i-15;return {prompt:'Найдите абсциссу точки локального максимума функции.',formula:`y = (x − (${a}))e⁻ˣ`,answer:a+1,audit:{a},hints:['Примени правило производной произведения.','Показательная функция e⁻ˣ положительна при любом x.','Знак производной определяется оставшимся линейным множителем.'],steps:[`y′ = e⁻ˣ − (x − (${a}))e⁻ˣ = (${a+1} − x)e⁻ˣ.`,`Производная положительна при x < ${a+1}, отрицательна при x > ${a+1}.`,`Максимум при x = ${a+1}.`]};});
// 13. Complete equation + selection. The checked answer is explicitly part b only.
family(13,'sin',1,'Синус и отбор корней','Тригонометрическое уравнение',i=>{const m=i-15;return {prompt:`а) Решите уравнение. б) Укажите все его корни на отрезке [${2*m}π; ${2*m+2}π]. В поле ответа введите только пункт б), общее решение запишите в черновике.`,formula:'2 sin x − 1 = 0',answer:`{${12*m+1}pi/6;${12*m+5}pi/6}`,audit:{m},hints:['Сведи уравнение к табличному значению синуса.','Запиши две серии с периодом 2π.','Отрезок составляет полный оборот; проверь обе серии и его концы.'],steps:['sin x = 1/2. Общее решение: x = π/6 + 2πk или x = 5π/6 + 2πk, k ∈ ℤ.',`На данном отрезке подходят x = ${12*m+1}π/6 и x = ${12*m+5}π/6. Других корней там нет.`],criteria:['Записаны обе серии общего решения.','Для обеих серий обоснован отбор на заданном отрезке.','В пункте б) перечислены все и только отобранные корни.']};});
family(13,'cos',3,'Квадратное относительно косинуса','Замена и граничные корни',i=>{const m=i-10;return {prompt:`а) Решите уравнение. б) Найдите все корни на отрезке [${2*m}π; ${2*m+2}π]. Проверяется ответ пункта б).`,formula:'2 cos²x − cos x − 1 = 0',answer:`{${2*m}pi;${6*m+2}pi/3;${6*m+4}pi/3;${2*m+2}pi}`,audit:{m},hints:['Обозначь cos x через t, не забывая −1 ≤ t ≤ 1.','Разложи квадратный трёхчлен на множители.','Запиши все серии и не исключай концы замкнутого отрезка.'],steps:['(2 cos x + 1)(cos x − 1) = 0. Поэтому cos x = −1/2 или cos x = 1.','Общее решение: x = ±2π/3 + 2πk или x = 2πk, k ∈ ℤ.',`На отрезке получаем ${2*m}π, ${6*m+2}π/3, ${6*m+4}π/3, ${2*m+2}π. Оба конца входят.`]};});
family(13,'exponential',2,'Показательное уравнение с отбором','Квадратная замена',i=>{const p=i%4+1,q=p+2,h=i-10;return {prompt:`а) Решите уравнение. б) Отберите корни на отрезке [${h}; ${h+q-1}]. Проверяется только пункт б).`,formula:`4^(x − (${h})) − ${2**p+2**q} · 2^(x − (${h})) + ${2**(p+q)} = 0`,answer:`{${h+p}}`,audit:{p,q,h},hints:['Положи t = 2^(x − h), где t > 0.','Разложи квадратный трёхчлен по t на два линейных множителя.','Вернись к x, затем отдельно проверь попадание каждого корня в отрезок.'],steps:[`При t = 2^(x − (${h})) > 0: (t − ${2**p})(t − ${2**q}) = 0.`,`Получаем x − (${h}) = ${p} или ${q}, то есть x = ${h+p} или ${h+q}.`,`На заданный отрезок входит только x = ${h+p}.`]};});
family(13,'log',3,'Логарифмическое уравнение с отбором','ОДЗ и замена',i=>{const p=i%4+1,q=p+2,h=i+1;return {prompt:`а) Решите уравнение. б) Отберите корни из [${1-h}; ${2**(p+1)-h}]. Проверяется только пункт б).`,formula:`(log₂(x + ${h}))² − ${p+q} log₂(x + ${h}) + ${p*q} = 0`,answer:`{${2**p-h}}`,audit:{p,q,h},hints:['Сначала потребуй положительность аргумента.','Обозначь логарифм через t и реши квадратное уравнение.','Оба найденных x проверь по ОДЗ и заданному отрезку.'],steps:[`ОДЗ: x > ${-h}. При t = log₂(x + ${h}): (t − ${p})(t − ${q}) = 0.`,`Корни: x = ${2**p-h} и x = ${2**q-h}. Оба входят в ОДЗ.`,`На указанный отрезок входит только ${2**p-h}.`]};});
// 14. Spatial geometry with explicit proof prompts.
family(14,'pyramid',1,'Две диагональные плоскости','Угол прямой и плоскости',i=>{const a=i+2,h=i+5;return {prompt:`В правильной четырёхугольной пирамиде SABCD сторона основания равна ${2*a}, высота SO равна ${h}; O — центр основания. а) Докажите, что плоскости SAC и SBD перпендикулярны. б) Найдите тангенс угла между SA и плоскостью основания.`,formula:`AB = ${2*a}, SO = ${h}`,answer:`${h}sqrt(2)/${2*a}`,answerKind:'number',diagram:'pyramid',audit:{a,h},hints:['Обе диагональные плоскости содержат высоту SO.','Сечение плоскостью основания перпендикулярно SO; в нём видны диагонали квадрата.','Для пункта б) используй прямоугольный треугольник SAO; AO — половина диагонали.'],steps:['SO перпендикулярна основанию и является линией пересечения SAC и SBD. Прямые AC и BD перпендикулярны SO и лежат в соответствующих плоскостях. Их угол — линейный угол двугранного угла.','Диагонали квадрата AC и BD перпендикулярны, значит плоскости SAC и SBD также перпендикулярны.',`Проекция SA на основание — AO; AO = ${a}√2. Поэтому tg ∠SAO = SO/AO = ${h}√2/${2*a}.`],criteria:['Обосновано, почему угол диагоналей является линейным углом двугранного угла.','Для угла SA с основанием использована проекция AO.','Длина AO и тангенс вычислены верно.']};});
family(14,'distance',2,'Расстояние до наклонной плоскости','Координаты куба',i=>{const a=i+2;return {prompt:`В кубе ABCDA₁B₁C₁D₁ ребро равно ${a}. а) Докажите, что плоскости ACD₁ и BB₁D перпендикулярны. б) Найдите расстояние от B до плоскости ACD₁.`,answer:`${a}sqrt(3)/3`,answerKind:'number',diagram:'cube',audit:{a},hints:['Введи координаты вдоль трёх рёбер из A.','Для доказательства сравни нормали двух плоскостей.','Расстояние от точки до плоскости можно выразить через её уравнение.'],steps:[`Пусть A(0,0,0), B(${a},0,0), C(${a},${a},0), D₁(0,${a},${a}).`,`Плоскость ACD₁: x − y + z = 0, её нормаль (1,−1,1). Плоскость BB₁D: x + y = ${a}, нормаль (1,1,0). Их скалярное произведение 0: плоскости перпендикулярны.`,`Расстояние от B: |${a} − 0 + 0|/√(1² + (−1)² + 1²) = ${a}√3/3.`],criteria:['Уравнения обеих плоскостей проверены на трёх неколлинеарных точках.','Скалярное произведение нормалей равно нулю.','В формулу расстояния подставлена точка B.']};});
family(14,'skew',3,'Скрещивающиеся прямые','Общий перпендикуляр',i=>{const a=i+2,b=i+3,h=i+5;return {prompt:`В прямоугольном параллелепипеде ABCDA₁B₁C₁D₁ рёбра AB = ${a}, AD = ${b}, AA₁ = ${h}. а) Докажите, что AB₁ и BC₁ скрещиваются. б) Найдите расстояние между ними.`,answer:`${a*b*h}/sqrt(${a*a*b*b+a*a*h*h+b*b*h*h})`,answerKind:'number',diagram:'cube',audit:{a,b,h},hints:['Введи координаты из вершины A.','Направления AB₁ и BC₁ не параллельны; проверь, могут ли прямые пересекаться.','Расстояние скрещивающихся прямых равно модулю смешанного произведения, делённому на длину векторного произведения направлений.'],steps:[`A(0,0,0), B(${a},0,0), B₁(${a},0,${h}), C₁(${a},${b},${h}). Направления u=(${a},0,${h}), v=(0,${b},${h}).`,`Точки AB₁ имеют y=0. На BC₁ это возможно только в B, но B не лежит на AB₁ при ${h}>0. Направления не пропорциональны: прямые скрещиваются.`,`u × v = (${-h*b},${-a*h},${a*b}); его длина √${h*h*b*b+a*a*h*h+a*a*b*b}.`,`Смешанное произведение с AB=(${a},0,0) по модулю равно ${a*b*h}. Расстояние равно ${a*b*h}/√${h*h*b*b+a*a*h*h+a*a*b*b}.`],criteria:['Непараллельность и отсутствие пересечения обоснованы отдельно.','Для смешанного произведения взят вектор между точками двух прямых.','Расстояние вычислено как положительное число.']};});
family(14,'section',3,'Сечение куба','Равносторонний треугольник',i=>{const a=i+2;return {prompt:`Ребро куба ABCDA₁B₁C₁D₁ равно ${a}. а) Докажите, что сечение плоскостью AB₁D₁ — равносторонний треугольник. б) Найдите площадь сечения.`,answer:`${a*a}sqrt(3)/2`,answerKind:'number',diagram:'cube',audit:{a},hints:['Убедись, что сечение состоит именно из трёх отрезков AB₁, B₁D₁, D₁A.','Каждый из них — диагональ квадратной грани.','Примени формулу площади равностороннего треугольника к найденной стороне.'],steps:[`В координатах куба 0≤x,y,z≤${a} плоскость имеет вид z=x+y. Условия z≤${a} дают в плоскости треугольник с вершинами A, B₁, D₁.`,`Все три стороны — диагонали граней и равны ${a}√2. Поэтому треугольник равносторонний.`,`S = (${a}√2)² · √3/4 = ${a*a}√3/2.`]};});
// 15. Inequalities, preserving all original domains.
family(15,'rational',1,'Три критические точки','Метод интервалов',i=>{const a=i-15,b=a+2,c=b+i%4+2;return {prompt:'Решите неравенство. Обоснуйте выбор интервалов.',formula:`(x − (${a}))(x − (${b})) / (x − (${c})) ≥ 0`,answer:`[${a};${b}]∪(${c};∞)`,audit:{a,b,c},hints:['Начни с запрета нуля знаменателя.','Размести два нуля и полюс в возрастающем порядке.','Определи знак на четырёх промежутках и включение каждой границы.'],steps:[`ОДЗ: x ≠ ${c}. Критические точки ${a} < ${b} < ${c}.`,`Знаки дроби слева направо: −, +, −, +.`,`При нестрогом неравенстве нули числителя входят, полюс исключается: [${a};${b}] ∪ (${c};+∞).`]};});
family(15,'logs',2,'Логарифм в числителе','Рационализация',i=>{const s=i+1,k=i%4+1,z=2**k-s,p=z+3;return {prompt:'Решите неравенство методом рационализации.',formula:`(log₂(x + ${s}) − ${k}) / (x − (${p})) ≤ 0`,answer:`[${z};${p})`,audit:{s,k,z,p},hints:['Запиши ОДЗ логарифма и ненулевой знаменатель.','Представь вычитаемое как логарифм степени двойки.','Замени разность логарифмов разностью аргументов по знаку.'],steps:[`ОДЗ: x > ${-s}, x ≠ ${p}.`,`Знак числителя совпадает со знаком x + ${s} − ${2**k} = x − (${z}).`,`Решаем (x − (${z}))/(x − (${p})) ≤ 0: [${z};${p}). Весь промежуток входит в ОДЗ.`]};});
family(15,'base',3,'Сдвиг переменного основания','Рационализация с основанием',i=>{const s=i+1;return {prompt:'Решите неравенство, учитывая переменное основание.',formula:`log₍ₓ₊${s}₎(x + ${s+2}) ≤ 2`,answer:`(${-s};${1-s})∪[${2-s};∞)`,audit:{s},hints:['Удобно обозначить x + s через t.','Для логарифма t > 0 и t ≠ 1.','Сравнение logₜ(t + 2) и logₜ(t²) учитывает знак t − 1.'],steps:[`t = x + ${s}, ОДЗ: t > 0, t ≠ 1.`,`Неравенство равносильно (t − 1)(t + 2 − t²) ≤ 0.`,`Поскольку t + 1 > 0, получаем (t − 1)(t − 2) ≥ 0. Значит t ∈ (0;1) ∪ [2;+∞).`,`Возвращаем сдвиг: x ∈ (${-s};${1-s}) ∪ [${2-s};+∞).`]};});
family(15,'absolute',3,'Изолированная точка','Модуль и деление',i=>{const a=i-12,d=i%5+2;return {prompt:'Решите неравенство. Проверьте случай нулевой правой части отдельно.',formula:`|(x − (${a}))(x − (${a+d}))| ≤ x − (${a})`,answer:`{${a}}∪[${a+d-1};${a+d+1}]`,audit:{a,d},hints:['Правая часть неотрицательна, поэтому x ≥ a.','Рассмотри равенство x = a отдельно до любого деления.','При x > a раздели на положительный множитель x − a.'],steps:[`Необходимо x ≥ ${a}. При x = ${a} обе части равны нулю.`,`При x > ${a} можно разделить на x − (${a}): |x − (${a+d})| ≤ 1.`,`Отсюда ${a+d-1} ≤ x ≤ ${a+d+1}. Этот отрезок лежит правее ${a}.`,`Ответ: {${a}} ∪ [${a+d-1};${a+d+1}].`]};});
// 16. Finance, with schedules spelled out rather than assumed.
family(16,'loan',1,'Кредит с равным уменьшением долга','Дифференцированные платежи',i=>{const S=100000*(i+1),n=4+i%6,r=10;return {prompt:`Кредит ${S} руб. взят на ${n} лет. В начале каждого года оставшийся долг увеличивают на 10%, затем в конце года вносят платёж. После каждого платежа долг уменьшается на одну и ту же величину; после последнего он равен нулю. Найдите общую сумму платежей в рублях.`,answer:decimal(S*(1+r/100*(n+1)/2)),audit:{S,n,r},hints:['Равномерно уменьшается основной долг, а не весь платёж.','Перед начислением процентов долги образуют арифметическую прогрессию.','К возвращённому основному долгу прибавь все проценты.'],steps:[`Погашение основного долга за год: ${S}/${n} руб.`,`Проценты начисляются на S, S(n−1)/n, …, S/n. Их сумма: 0,1 · S(n+1)/2.`,`Всего: S + 0,1 · S(n+1)/2 = ${decimal(S*(1+r/100*(n+1)/2))} руб.`]};});
family(16,'annuity',2,'Два одинаковых платежа','Рекуррентная схема долга',i=>{const S=110000*(i+1),X=72000*(i+1);return {prompt:`Кредит ${S} руб. погашают двумя одинаковыми ежегодными платежами. Перед каждым платежом долг увеличивается на 20%. После второго платежа долг равен нулю. Найдите размер каждого платежа в рублях.`,answer:X,audit:{S,X},hints:['Обозначь одинаковый платёж через X.','После первого платежа долг равен 1,2S − X.','Начисли проценты на оставшийся долг и вычти второй платёж.'],steps:['После первого платежа: D₁ = 1,2S − X.','После второго: 1,2(1,2S − X) − X = 0, то есть 1,44S = 2,2X.',`X = 36S/55 = ${X} руб.`]};});
family(16,'deposit',3,'Вклад с пополнением','Сложные проценты',i=>{const S=50000*(i+1),D=10000*(i+3),F=decimal((S*1.1+D)*1.1);return {prompt:`На вклад внесли ${S} руб. Банк начисляет 10% в конце каждого года. Сразу после первого начисления вклад пополнили на неизвестную сумму D. После второго начисления на счёте стало ${F} руб. Найдите D в рублях.`,answer:D,audit:{S,D,F:Number(F)},hints:['Раздели операции по годам, не начисляй проценты на пополнение раньше его внесения.','После первого года до пополнения на счёте 1,1S.','Итог равен (1,1S + D) · 1,1.'],steps:[`После первого года и пополнения: 1,1 · ${S} + D.`,`(1,1 · ${S} + D) · 1,1 = ${F}.`,`D = ${F}/1,1 − 1,1 · ${S} = ${D} руб.`]};});
family(16,'profit',3,'Цена максимальной прибыли','Экономическая оптимизация',i=>{const b=i%4+2,c=i+10,p=c+i+20,a=b*(2*p-c);return {prompt:`При цене p руб. продаётся Q(p) = ${a} − ${b}p единиц товара. Себестоимость единицы — ${c} руб. Допустимы p ≥ ${c} и Q(p) ≥ 0. Найдите цену p, при которой прибыль максимальна.`,formula:`Π(p) = (p − ${c})(${a} − ${b}p)`,answer:p,audit:{a,b,c,p},hints:['Прибыль — выручка минус все затраты на проданные единицы.','Получится квадратный трёхчлен с отрицательным старшим коэффициентом.','Найди вершину и проверь допустимый диапазон цены.'],steps:[`Π(p) = −${b}p² + ${a+b*c}p − ${a*c}.`,`Вершина: p = (${a} + ${b} · ${c})/(2 · ${b}) = ${p}.`,`Цена ${p} лежит между ${c} и ${a/b}, поэтому максимум допустим.`]};});
// 17. Plane geometry with proof and numerical part.
family(17,'inradius',1,'Окружность в прямоугольном треугольнике','Площадь и радиус',i=>{const k=i+1;return {prompt:`В прямоугольном треугольнике ABC катеты AC = ${3*k}, BC = ${4*k}. а) Докажите, что его площадь равна произведению радиуса вписанной окружности на полупериметр. б) Найдите этот радиус.`,answer:k,diagram:'right-triangle',audit:{k},hints:['Соедини центр вписанной окружности с вершинами.','Расстояния центра до всех трёх сторон равны радиусу r.','Сложи площади трёх треугольников и сравни с площадью через катеты.'],steps:['Площади треугольников с общей вершиной в центре вписанной окружности равны ar/2, br/2, cr/2. Их сумма равна r(a+b+c)/2 = rs.',`Гипотенуза ${5*k}; полупериметр s = ${6*k}.`,`Площадь S = ${3*k} · ${4*k}/2 = ${6*k*k}, значит r = S/s = ${k}.`],criteria:['Центр соединён с вершинами, площади трёх частей сложены.','Обосновано равенство высот этих треугольников радиусу r.','Гипотенуза, полупериметр и радиус вычислены верно.']};});
family(17,'trapezoid',2,'Диагонали трапеции','Подобие и площади',i=>{const a=i+2,b=i+5,h=i%6+3;return {prompt:`В трапеции ABCD основания AB = ${a}, CD = ${b}, высота равна ${h}. Диагонали AC и BD пересекаются в O. а) Докажите подобие треугольников AOB и COD. б) Найдите площадь AOB.`,answer:`${h*a*a}/${2*(a+b)}`,answerKind:'number',diagram:'trapezoid',audit:{a,b,h},hints:['Используй вертикальные углы и углы при параллельных основаниях.','Отношение высот подобных треугольников равно отношению оснований.','Сумма расстояний от O до оснований равна высоте трапеции.'],steps:['∠AOB = ∠COD как вертикальные; ∠ABO = ∠CDO при AB ∥ CD. Значит треугольники подобны.',`Их высоты относятся как ${a}:${b}, а сумма высот равна ${h}. Высота AOB равна ${h*a}/${a+b}.`,`S_AOB = AB · h_AOB/2 = ${h*a*a}/${2*(a+b)}.`],criteria:['Для подобия приведены две пары равных углов.','Высоты разделены в отношении AB:CD, а не наоборот.','Площадь вычислена с основанием AB и соответствующей высотой.']};});
family(17,'centers',3,'Расстояние между центрами','Координатный метод',i=>{const k=i+1;return {prompt:`Стороны треугольника ABC равны AB = ${14*k}, AC = ${13*k}, BC = ${15*k}. а) Докажите, что высота из C к прямой AB равна ${12*k}. б) Найдите расстояние между центрами вписанной и описанной окружностей.`,answer:`${k}sqrt(65)/8`,answerKind:'number',diagram:'triangle',audit:{k},hints:['Обозначь проекцию AC на AB через x и запиши два равенства Пифагора.','Для пункта б) удобно взять A(0,0), B(14k,0), C(5k,12k).','Центр вписанной окружности выражается взвешенным средним вершин; центр описанной равноудалён от них.'],steps:[`Пусть основание высоты H, AH = x. Из x² + CH² = (${13*k})² и (${14*k} − x)² + CH² = (${15*k})² получаем x = ${5*k}; CH = ${12*k}.`,`В выбранных координатах S = ${84*k*k}, s = ${21*k}, r = ${4*k}. Центр I = (15A + 13B + 14C)/42 = (${6*k};${4*k}).`,`Центр описанной окружности лежит на x = ${7*k}. Из OA² = OC² получаем O = (${7*k};${33*k}/8).`,`OI = √((${k})² + (${k}/8)²) = ${k}√65/8.`],criteria:['Положение основания высоты найдено из двух равенств Пифагора.','Координаты I и O обоснованы свойствами центров.','Расстояние между центрами вычислено по координатам.']};});
family(17,'tangent-trapezoid',3,'Трапеция с вписанной окружностью','Касательные и высота',i=>{const m=i+1,n=i+3,a=2*m*m,b=2*n*n;return {prompt:`В равнобедренную трапецию с основаниями ${a} и ${b} вписана окружность. а) Докажите, что квадрат высоты равен произведению оснований. б) Найдите площадь трапеции.`,answer:2*m*n*(m*m+n*n),diagram:'trapezoid',audit:{m,n,a,b},hints:['Суммы противоположных сторон описанного четырёхугольника равны.','Каждая боковая сторона равна полусумме оснований.','Опусти две высоты: горизонтальная проекция боковой стороны равна полуразности оснований.'],steps:['Из равенства отрезков касательных получаем сумму оснований, равную сумме боковых сторон. В равнобедренной трапеции каждая боковая сторона l = (a+b)/2.','По Пифагору h² = l² − ((b−a)/2)² = ((a+b)² − (b−a)²)/4 = ab.',`h = √(${a} · ${b}) = ${2*m*n}.`,`S = (${a} + ${b}) · ${2*m*n}/2 = ${2*m*n*(m*m+n*n)}.`]};});
