family(18,'exponential',1,'Два положительных значения замены','Функция f(t)',i=>{const b=i+1;return {prompt:'Найдите все значения параметра a, при которых уравнение имеет ровно два различных действительных корня. Используйте анализ функции.',formula:`4ˣ − ${2*b} · 2ˣ = a`,answer:`(${-b*b};0)`,audit:{b},hints:['Замени 2ˣ на t и сразу запиши область t.','Выдели полный квадрат в f(t) = t² − 2bt.','Сравни уровень a с вершиной и уровнем в исключённой точке t = 0.'],steps:[`t = 2ˣ > 0; f(t) = (t − ${b})² − ${b*b}.`,`Минимум равен ${-b*b}. При ${-b*b} < a < 0 горизонталь пересекает обе ветви в положительных t.`,`В вершине корень один; при a = 0 значение t = 0 запрещено. При a > 0 положительный корень только один. Ответ: (${-b*b};0).`]};});
family(18,'radical',2,'Допустимый ноль замены','Параметр под корнем',i=>{const b=i+1,c=i+3;return {prompt:'Найдите все значения a, при которых уравнение имеет ровно два различных действительных корня.',formula:`x + ${c} − ${2*b}√(x + ${c}) = a`,answer:`(${-b*b};0]`,audit:{b,c},hints:['В замене t = √(x + c) ноль допустим.','Исследуй параболу на полуоси t ≥ 0.','Уровень f(0) требует отдельной проверки; не исключай границу автоматически.'],steps:[`ОДЗ x ≥ ${-c}. Замена t = √(x + ${c}) взаимно однозначна при t ≥ 0.`,`f(t) = (t − ${b})² − ${b*b}. При ${-b*b} < a < 0 получаются два t.`,`При a = 0 корни t = 0 и t = ${2*b} допустимы. При a = ${-b*b} корень один. Ответ: (${-b*b};0].`]};});
family(18,'absolute',3,'Три корня у чётной функции','Модуль и случаи',i=>{const m=i+2;return {prompt:'Найдите все значения a, при которых уравнение имеет ровно три различных действительных корня.',formula:`|x² − ${m}| = a`,answer:`{${m}}`,audit:{m},hints:['Отрицательная правая часть невозможна.','При неотрицательной a получаются ветви x² = m + a и x² = m − a.','Нечётное число корней появляется, когда одна ветвь даёт единственный нулевой корень.'],steps:[`При a < 0 решений нет. При a = 0 две ветви совпадают и дают два корня.`,`Если 0 < a < ${m}, корней четыре. Если a = ${m}, получаем x = 0 и x = ±√${2*m}, всего три.`,`При a > ${m} остаются два корня. Ответ: a = ${m}.`]};});
family(18,'interval',3,'Один корень на открытом интервале','Параметр и ограничения',i=>{const b=i+3,d=i%3+1,R=b+d;return {prompt:`Найдите все a, при которых уравнение имеет ровно один корень на интервале (1; ${2**R}).`,formula:`(log₂x)² − ${2*b}log₂x = a`,answer:`{${-b*b}}∪[${d*d-b*b};0)`,audit:{b,d,R},hints:['Замена t = log₂x переводит исходный интервал в 0 < t < R.','Вершина t = b лежит внутри интервала; выпиши значения f в вершине и на обоих концах.','Проверь отдельно уровень правого исключённого конца и уровень вершины.'],steps:[`t = log₂x ∈ (0;${R}), f(t) = (t − ${b})² − ${b*b}.`,`Минимум равен ${-b*b}, f(0) = 0, f(${R}) = ${d*d-b*b}. При a = ${-b*b} есть ровно один корень.`,`При ${-b*b} < a < ${d*d-b*b} корня два. При ${d*d-b*b} ≤ a < 0 один корень правой ветви вышел из открытого интервала, а левый ещё допустим.`,`При a = 0 оба корня t = 0 и t = ${2*b} вне интервала; при a > 0 также нет корней. Ответ: {${-b*b}} ∪ [${d*d-b*b};0).`]};});
