family(19,'gcd',1,'Наибольший общий делитель и сумма','Оценка и пример',i=>{const d=2*i+3,S=3*d;return {prompt:`Два различных натуральных числа имеют сумму ${S}. а) Может ли их НОД равняться ${d}? Приведите пример. б) Может ли НОД равняться ${d+1}? Обоснуйте. в) Найдите наибольший возможный НОД. Проверяется ответ пункта в).`,answer:d,audit:{d,S},hints:['Любой общий делитель чисел делит их сумму.','Если числа различны и кратны D, их сумма не меньше D + 2D.','Для достижения оценки попробуй числа D и 2D.'],steps:[`а) Да: числа ${d} и ${2*d} имеют сумму ${S} и НОД ${d}.`,`б) Нет: НОД должен делить ${S}. Но ${S} = 3(${d+1}) − 3, а ${d+1} > 3, поэтому он не делит сумму.`,`в) Для различных натуральных кратных D сумма ≥ 3D, значит D ≤ ${S}/3 = ${d}. Пример из а) достигает оценки; максимум ${d}.`],criteria:['Для пункта а) приведён пример с проверкой суммы и НОД.','Невозможность пункта б) обоснована делимостью суммы.','В пункте в) есть и верхняя оценка, и достигающий её пример.']};});
family(19,'digits',2,'Сумма цифр и минимальное число','Делимость на 9',i=>{const s=i+3;let remaining=s,number='';for(let pos=0;pos<4;pos++){let digit=Math.max(pos===0?1:0,remaining-9*(3-pos));number+=digit;remaining-=digit;}return {prompt:`Рассматриваются четырёхзначные натуральные числа с суммой цифр ${s}. а) Может ли такое число делиться на 9? б) Докажите, что все такие числа дают одинаковый остаток при делении на 9. в) Найдите наименьшее такое число. Проверяется пункт в).`,answer:Number(number),audit:{s},hints:['Используй признак делимости и сравнение числа с суммой его цифр по модулю 9.','Чтобы минимизировать число, минимизируй цифры слева направо.','На каждом шаге оставшаяся сумма должна помещаться в оставшиеся разряды; каждый вмещает не больше 9.'],steps:[`а) ${s%9===0?'Да':'Нет'}: сумма цифр ${s} ${s%9===0?'делится':'не делится'} на 9.`,`б) 10 ≡ 1 (mod 9), поэтому число и сумма его цифр сравнимы по модулю 9. Остаток всегда ${s%9}.`,`в) Минимизируем старший разряд, оставляя возможность набрать остаток суммы в младших. Затем повторяем для каждого разряда. Получаем ${number}.`,`У ${number} четыре цифры, их сумма ${s}. Любое меньшее число отличалось бы меньшей цифрой на первой отличающейся позиции; тогда оставшиеся разряды не набрали бы необходимую сумму.`]};});
family(19,'fractions',3,'Уравнение в натуральных числах','Разложение на множители',i=>{const n=i+2;return {prompt:`Натуральные x, y удовлетворяют 1/x + 1/y = 1/${n}, причём x ≤ y. а) Приведите пример решения. б) Докажите равенство (x − ${n})(y − ${n}) = ${n*n}. в) Найдите наибольшее возможное y. Проверяется пункт в).`,answer:n*n+n,audit:{n},hints:['Для примера попробуй одинаковые x и y.','Умножь равенство на nxy, перенеси члены и добавь n².','Докажи x > n и y > n. Тогда оба новых множителя — положительные целые числа.'],steps:[`а) Подходит x = y = ${2*n}.`,`б) Из ${n}(x+y) = xy получаем xy − ${n}x − ${n}y + ${n*n} = ${n*n}, то есть нужное разложение.`,`Так как 1/x < 1/${n}, имеем x > ${n}; аналогично y > ${n}. Поэтому минимальное x − ${n} равно 1.`,`в) Наибольший y получается при x − ${n} = 1, y − ${n} = ${n*n}. Значит y = ${n*n+n}; x = ${n+1} ≤ y. Оценка достигается.`]};});
family(19,'pigeonhole',3,'Числа без делимости','Принцип Дирихле',i=>{const n=i+3;return {prompt:`Из чисел 1, 2, …, ${2*n} выбирают несколько так, чтобы никакое из выбранных чисел не делилось на другое. а) Приведите пример выбора ${n} чисел. б) Докажите, что выбрать ${n+1} чисел с таким свойством нельзя. в) Найдите наибольшее возможное количество выбранных чисел. Проверяется пункт в).`,answer:n,audit:{n},hints:['Для примера рассмотрим числа строго больше половины верхней границы.','Представь каждое число в виде нечётного числа, умноженного на степень 2.','Чисел с одним нечётным множителем нельзя взять два: одно будет делиться на другое.'],steps:[`а) Выбираем ${n+1}, ${n+2}, …, ${2*n}. Ни одно не делится на другое: удвоение даже наименьшего уже больше ${2*n}.`,`б) У каждого числа единственно выделяется нечётная часть. Возможных нечётных частей среди 1,…,${2*n} ровно ${n}. Если выбрать ${n+1} чисел, у двух совпадёт нечётная часть.`,`Эти два числа имеют вид u·2ᵃ и u·2ᵇ; одно делится на другое. Противоречие.`,`в) Верхняя оценка ${n} достигается примером из а), поэтому максимум ${n}.`]};});
